const leads = $input.all().map(i => i.json);

// Count by tier
const highLeads = leads.filter(l => l.lead_tier === 'high');
const midLeads  = leads.filter(l => l.lead_tier === 'mid');
const lowLeads  = leads.filter(l => l.lead_tier === 'low');

// Count by status
const newLeads      = leads.filter(l => l.status === 'new');
const completed     = leads.filter(l => l.status === 'sequence_complete');

// Average score
const avgScore = leads.length
  ? (leads.reduce((sum, l) => sum + (parseFloat(l.lead_score) || 0), 0) / leads.length).toFixed(1)
  : 0;

// Today's leads
const today = new Date().toISOString().split('T')[0];
const todayLeads = leads.filter(l => 
  l.timestamp && l.timestamp.startsWith(today)
);

// Build Slack message
const message = `
📊 *Daily Lead Digest — ${new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata' })}*

━━━━━━━━━━━━━━━━━━━━━
📈 *Pipeline Summary*
- Total leads: *${leads.length}*
- New today: *${todayLeads.length}*
- Avg lead score: *${avgScore}/100*

🎯 *Tier Breakdown*
- 🔥 High tier: *${highLeads.length}*
- 🟡 Mid tier:  *${midLeads.length}*
- 🔵 Low tier:  *${lowLeads.length}*

📬 *Follow-up Status*
- In sequence: *${newLeads.length}*
- Completed:   *${completed.length}*

${todayLeads.length > 0 
  ? `*New leads today:*\n` + todayLeads.map(l => 
    `  • ${l.full_name} — ${l.company} — Score: ${l.lead_score} [${l.lead_tier}]`
  ).join('\n')
  : '📭 No new leads today'
}
━━━━━━━━━━━━━━━━━━━━━
`.trim();

return [{ json: { digest_message: message } }];

